let loveMultiplier = 0.5; // multiplier for the love in each generation
let LOVE = 0.01; // main parameter for the LoveAnimator algorithm

function setup() {
    createCanvas(600, 600, WEBGL);
}

function draw() {
    background(255);
    rotateY(angle);
    rotateX(angle);
    translate(0, 0, -150);
    heartFractal(numPoints, numGenerations, initialRadius, radiusMultiplier, loveMultiplier, LOVE);
    angle += 0.01;
}

function heartFractal(points, generations, radius, radiusMultiplier, loveMultiplier, LOVE) {
    if (generations > 0) {
        let angle = TWO_PI / points;
        let halfAngle = angle / 2;
        beginShape();
        for (let i = 0; i < points; i += 2) {
            let x = radius * cos(i * angle);
            let y = radius * sin(i * angle);
            vertex(x, y, 0);
        }
        endShape(CLOSE);

        radius *= radiusMultiplier;
        loveMultiplier *= 1 - LOVE;
        LOVE *= loveMultiplier;
        heartFractal(points, generations - 1, radius, radiusMultiplier, loveMultiplier, LOVE);

        if (loveMultiplier < LOVE) {
            LOVE = 0;
            radius = initialRadius;
            loveMultiplier = 1;
            generations--;
        }

        beginShape();
        for (let i = 0; i < points; i += 2) {
            let x = radius * cos(i * angle);
            let y = radius * sin(i * angle);
            vertex(x, y, 0);
        }
        endShape(CLOSE);
    }
}
```

